async function fetchJadwalDns(s){try{const a=await fetch(`/api/presensi/jdldnsall?periode=${s}`,{method:"GET"});if(a.ok)return await a.json();console.error("Error fetching data:",a.status)}catch(a){console.error("Error:",a)}}document.getElementById("jadwalDNSModal").addEventListener("click",async function(){let s=document.getElementById("jadwal-list"),a=document.getElementById("shift-list");s.innerHTML="",a.innerHTML="";let n=document.getElementById("periode").value,c=document.getElementById("jadwalPeriode");c.innerHTML=new Intl.DateTimeFormat("id-ID",{month:"long",year:"numeric"}).format(new Date(n)),dataJadwal=await fetchJadwalDns(n);let d=1,l=[];dataJadwal.list.forEach(e=>{if(e.state==0){const t=document.createElement("span");t.className="badge shift-bg-libur",t.textContent=e.type,a.appendChild(t)}else{const t=document.createElement("span");t.className="badge shift-bg-"+d,t.textContent=e.type,a.appendChild(t),l.push({state:e.type,type:d})}d++}),dataJadwal.data.forEach(e=>{if(e.dnsType.state==0){const t=document.createElement("div");t.className="card jadwal-card shift-libur",t.innerHTML=`
                          <div class="card-body p-3">
                                <div class="d-flex justify-content-between align-items-center flex-wrap">
                                    <div class="flex-grow-1"> 
                                        <p class="mb-0 fw-bold fs-6 text-dark">${e.date}</p>
                                    </div>
                                    <div class="text-end ms-2"> 
                                        <span class="badge shift-bg-libur me-1">${e.dnsType.type}</span>
                                        <span class="text-muted small d-block d-sm-inline">(${e.dnsType.start_min} - ${e.dnsType.end_min})</span> 
                                    </div>
                                </div>
                            </div>`,s.appendChild(t)}else{const t=document.createElement("div");let i=l.find(r=>r.state==e.dnsType.type);t.className="card jadwal-card shift-"+i.type,t.innerHTML=`
                          <div class="card-body p-3">
                                <div class="d-flex justify-content-between align-items-center flex-wrap">
                                    <div class="flex-grow-1"> 
                                        <p class="mb-0 fw-bold fs-6 text-dark">${e.date}</p>
                                    </div>
                                    <div class="text-end ms-2"> 
                                        <span class="badge shift-bg-${i.type} me-1">${e.dnsType.type}</span>
                                        <span class="text-muted small d-block d-sm-inline">(${e.dnsType.start_min} - ${e.dnsType.end_min})</span> 
                                    </div>
                                </div>
                            </div>`,s.appendChild(t)}})});
